uid_t keep = (uid_t)-1;       // Sentinel: Do not change this ID
uid_t new_euid = 1000;

// Change only the effective ID (EUID). RUID and SUID remain
// unchanged (due to '-1' sentinel value).
// Requires CAP_SETUID if new_euid is not one of the current IDs.
int status = setresuid32(keep, new_euid, keep);

